<?php require __DIR__.'/inc/page_helpers.php';login_required();if(!page_post()){go('/');}check_csrf();$type=(string)($_POST['type']??'');$id=(int)($_POST['id']??0);$reason=trim((string)($_POST['reason']??''));$allowed=['user','game','item','forum_topic','forum_reply'];if(!in_array($type,$allowed,true)||$id<1||$reason===''){notice('Invalid report.','error');go('/');}$table=['user'=>'users','game'=>'games','item'=>'catalog_items','forum_topic'=>'forum_topics','forum_reply'=>'forum_replies'][$type];$q=$db->prepare("SELECT id FROM {$table} WHERE id=?");$q->execute([$id]);if(!$q->fetch()){notice('Content not found.','error');go('/');}$db->prepare('INSERT INTO moderation_reports(reporter_id,target_type,target_id,reason) VALUES(?,?,?,?)')->execute([$currentUser['id'],$type,$id,mb_substr($reason,0,1000)]);notice('Report sent to moderators.');go('/');